gRPC 是 Google 开发的高性能 RPC 框架，使用 Protocol Buffers 作为接口定义语言和序列化格式。


## Protocol Buffers

Protobuf 是一种语言中立、平台中立的序列化格式：
```protobuf
syntax = "proto3";

option csharp_namespace = "MyApp.Protos";

message User {
    int32 id = 1;
    string name = 2;
    string email = 3;
    repeated string roles = 4;
}

message GetUserRequest {
    int32 id = 1;
}

message CreateUserRequest {
    string name = 1;
    string email = 2;
}

service UserService {
    rpc GetUser (GetUserRequest) returns (User);
    rpc CreateUser (CreateUserRequest) returns (User);
    rpc ListUsers (Empty) returns (stream User);
}
```

## gRPC 服务实现

```csharp
public class UserServiceImpl : UserService.UserServiceBase
{
    private readonly ILogger<UserServiceImpl> _logger;
    private readonly IUserRepository _repository;

    public UserServiceImpl(ILogger<UserServiceImpl> logger, IUserRepository repository)
    {
        _logger = logger;
        _repository = repository;
    }

    public override async Task<User> GetUser(GetUserRequest request, ServerCallContext context)
    {
        var user = await _repository.GetByIdAsync(request.Id);
        if (user == null)
        {
            throw new RpcException(new Status(StatusCode.NotFound, "User not found"));
        }

        return new User
        {
            Id = user.Id,
            Name = user.Name,
            Email = user.Email
        };
    }

    public override async Task<User> CreateUser(CreateUserRequest request, ServerCallContext context)
    {
        var user = new Models.User
        {
            Name = request.Name,
            Email = request.Email
        };

        await _repository.AddAsync(user);

        return new User
        {
            Id = user.Id,
            Name = user.Name,
            Email = user.Email
        };
    }

    // 服务端流式
    public override async Task ListUsers(
        Empty request,
        IServerStreamWriter<User> responseStream,
        ServerCallContext context)
    {
        var users = await _repository.GetAllAsync();
        foreach (var user in users)
        {
            await responseStream.WriteAsync(new User
            {
                Id = user.Id,
                Name = user.Name,
                Email = user.Email
            });
        }
    }
}
```


## gRPC 客户端

```csharp
// 注册客户端
builder.Services.AddGrpcClient<UserService.UserServiceClient>(options =>
{
    options.Address = new Uri("https://localhost:5001");
});

// 使用客户端
public class UserGrpcService
{
    private readonly UserService.UserServiceClient _client;

    public UserGrpcService(UserService.UserServiceClient client)
    {
        _client = client;
    }

    public async Task<User> GetUserAsync(int id)
    {
        return await _client.GetUserAsync(new GetUserRequest { Id = id });
    }

    // 服务端流式
    public async Task<List<User>> ListUsersAsync()
    {
        var users = new List<User>();
        using var call = _client.ListUsers(new Empty());

        await foreach (var user in call.ResponseStream.ReadAllAsync())
        {
            users.Add(user);
        }

        return users;
    }
}
```

## 流式通信

**服务端流式**：服务器返回流
```protobuf
rpc ListUsers (Empty) returns (stream User);
```

**客户端流式**：客户端发送流
```protobuf
rpc CreateUsers (stream CreateUserRequest) returns (CreateUsersResponse);
```

**双向流式**：双方都发送流
```protobuf
rpc Chat (stream ChatMessage) returns (stream ChatMessage);
```


## gRPC 与 REST 对比

**gRPC 优点**：
- 高性能（二进制序列化）
- 强类型（Protobuf 定义）
- 流式通信
- 跨语言支持
- 自动生成客户端代码

**REST 优点**：
- 简单易懂
- 浏览器支持
- 缓存友好
- 调试方便
- 生态成熟

**选择建议**：
- 微服务内部通信：gRPC
- 对外公开 API：REST
- 实时通信：gRPC 流式
- 浏览器调用：REST 或 gRPC-Web


## gRPC-Web

浏览器不支持 HTTP/2 trailers，需要 gRPC-Web：
```csharp
// 服务端配置
app.UseGrpcWeb(new GrpcWebOptions { DefaultEnabled = true });

app.MapGrpcService<UserServiceImpl>().EnableGrpcWeb();
```


## 错误处理

```csharp
public override async Task<User> GetUser(GetUserRequest request, ServerCallContext context)
{
    var user = await _repository.GetByIdAsync(request.Id);
    if (user == null)
    {
        throw new RpcException(new Status(StatusCode.NotFound, $"User {request.Id} not found"));
    }
    return user;
}

// 客户端错误处理
try
{
    var user = await _client.GetUserAsync(new GetUserRequest { Id = 1 });
}
catch (RpcException ex) when (ex.StatusCode == StatusCode.NotFound)
{
    Console.WriteLine("User not found");
}
catch (RpcException ex)
{
    Console.WriteLine($"gRPC error: {ex.Status}");
}
```


## 拦截器

```csharp
public class LoggingInterceptor : Interceptor
{
    private readonly ILogger<LoggingInterceptor> _logger;

    public LoggingInterceptor(ILogger<LoggingInterceptor> logger)
    {
        _logger = logger;
    }

    public override AsyncUnaryCall<TResponse> AsyncUnaryCall<TRequest, TResponse>(
        TRequest request,
        ClientInterceptorContext<TRequest, TResponse> context,
        AsyncUnaryCallContinuation<TRequest, TResponse> continuation)
    {
        _logger.LogInformation($"Calling {context.Method.FullName}");
        return continuation(request, context);
    }
}

// 注册拦截器
builder.Services.AddGrpcClient<UserService.UserServiceClient>(options =>
{
    options.Address = new Uri("https://localhost:5001");
}).AddInterceptor<LoggingInterceptor>();
```

using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Grpc.Core;
using Grpc.Net.Client;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace GrpcProtobufDemo
{
    // Proto 文件生成的类（示例）
    // 实际项目中由 .proto 文件自动生成
    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
    }

    public class GetUserRequest
    {
        public int Id { get; set; }
    }

    public class CreateUserRequest
    {
        public string Name { get; set; }
        public string Email { get; set; }
    }

    // 服务实现
    public class UserServiceImpl
    {
        private readonly ILogger<UserServiceImpl> _logger;
        private readonly Dictionary<int, User> _users = new();
        private int _nextId = 1;

        public UserServiceImpl(ILogger<UserServiceImpl> logger)
        {
            _logger = logger;
        }

        public Task<User> GetUser(GetUserRequest request, ServerCallContext context)
        {
            _logger.LogInformation($"GetUser called with id: {request.Id}");

            if (_users.TryGetValue(request.Id, out var user))
            {
                return Task.FromResult(user);
            }

            throw new RpcException(new Status(StatusCode.NotFound, $"User {request.Id} not found"));
        }

        public Task<User> CreateUser(CreateUserRequest request, ServerCallContext context)
        {
            _logger.LogInformation($"CreateUser called with name: {request.Name}");

            var user = new User
            {
                Id = _nextId++,
                Name = request.Name,
                Email = request.Email
            };

            _users[user.Id] = user;
            return Task.FromResult(user);
        }

        // 服务端流式
        public async Task ListUsers(
            Empty request,
            IServerStreamWriter<User> responseStream,
            ServerCallContext context)
        {
            _logger.LogInformation("ListUsers called");

            foreach (var user in _users.Values)
            {
                await responseStream.WriteAsync(user);
            }
        }
    }

    // 客户端服务
    public class UserGrpcClient
    {
        private readonly UserService.UserServiceClient _client;
        private readonly ILogger<UserGrpcClient> _logger;

        public UserGrpcClient(UserService.UserServiceClient client, ILogger<UserGrpcClient> logger)
        {
            _client = client;
            _logger = logger;
        }

        public async Task<User> GetUserAsync(int id)
        {
            try
            {
                return await _client.GetUserAsync(new GetUserRequest { Id = id });
            }
            catch (RpcException ex) when (ex.StatusCode == StatusCode.NotFound)
            {
                _logger.LogWarning($"User {id} not found");
                return null;
            }
        }

        public async Task<User> CreateUserAsync(string name, string email)
        {
            return await _client.CreateUserAsync(new CreateUserRequest
            {
                Name = name,
                Email = email
            });
        }

        public async Task<List<User>> ListUsersAsync()
        {
            var users = new List<User>();
            using var call = _client.ListUsers(new Empty());

            await foreach (var user in call.ResponseStream.ReadAllAsync())
            {
                users.Add(user);
            }

            return users;
        }
    }

    // 拦截器
    public class LoggingInterceptor : Interceptor
    {
        private readonly ILogger<LoggingInterceptor> _logger;

        public LoggingInterceptor(ILogger<LoggingInterceptor> logger)
        {
            _logger = logger;
        }

        public override AsyncUnaryCall<TResponse> AsyncUnaryCall<TRequest, TResponse>(
            TRequest request,
            ClientInterceptorContext<TRequest, TResponse> context,
            AsyncUnaryCallContinuation<TRequest, TResponse> continuation)
        {
            _logger.LogInformation($"Calling {context.Method.FullName}");
            var call = continuation(request, context);
            return new AsyncUnaryCall<TResponse>(
                HandleResponse(call.ResponseAsync),
                call.ResponseHeadersAsync,
                call.GetStatus,
                call.GetTrailers,
                call.Dispose);
        }

        private async Task<TResponse> HandleResponse<TResponse>(Task<TResponse> inner)
        {
            try
            {
                return await inner;
            }
            catch (RpcException ex)
            {
                _logger.LogError(ex, "gRPC call failed");
                throw;
            }
        }
    }

    // 服务配置
    public static class GrpcServiceCollectionExtensions
    {
        public static IServiceCollection AddGrpcServices(this IServiceCollection services)
        {
            services.AddGrpc();
            return services;
        }

        public static IServiceCollection AddGrpcClients(this IServiceCollection services,
            string userServiceUrl)
        {
            services.AddGrpcClient<UserService.UserServiceClient>(options =>
            {
                options.Address = new Uri(userServiceUrl);
            })
            .AddInterceptor<LoggingInterceptor>();

            services.AddScoped<UserGrpcClient>();
            return services;
        }
    }

    // 应用配置
    public static class GrpcApplicationBuilderExtensions
    {
        public static IApplicationBuilder UseGrpcServices(this IApplicationBuilder app)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapGrpcService<UserServiceImpl>();
            });
            return app;
        }
    }

    // 示例：使用 gRPC 客户端
    public class UserApiService
    {
        private readonly UserGrpcClient _grpcClient;

        public UserApiService(UserGrpcClient grpcClient)
        {
            _grpcClient = grpcClient;
        }

        public async Task<User> GetUserAsync(int id)
        {
            return await _grpcClient.GetUserAsync(id);
        }

        public async Task<User> CreateUserAsync(string name, string email)
        {
            return await _grpcClient.CreateUserAsync(name, email);
        }

        public async Task<IEnumerable<User>> GetAllUsersAsync()
        {
            return await _grpcClient.ListUsersAsync();
        }
    }
}
